mapper.select:
select 
from evaluation_date_settings bp
where bp.setting_id = #{settingId}

select count(*)
from evaluation_date_settings bp
where bp.active_yn = 'Y'
  and bp.evaluation_year = #{evaluationYear}


          and bp.area_code = #{areaCode}


          and bp.area_code is null




          and bp.organization_code = #{organizationCode}


          and bp.organization_code is null




          and bp.user_type_code = #{userTypeCode}


          and bp.user_type_code is null


  and tsrange(bp.start_at, bp.end_at, '[]') && tsrange(#{startAt}, #{endAt}, '[]')

      and bp.setting_id != #{settingId}

select count(*)
from evaluation_organization_mappings eom
where eom.user_id = #{userId}
  and eom.organization_code = #{organizationCode}
  and eom.business_type = 'FACULTY_ACHIEVEMENT'
  and eom.data_scope in ('DEPARTMENT','COLLEGE','BUSINESS','ALL')

